rows.QueryDefinition:
let
    // 1) Daten aus Dynamics laden
    dbo_contract = Value.NativeQuery(
        CommonDataService.Database("psop.crm4.dynamics.com"),
        "SELECT 
    incident0.*
   FROM 
    Incident AS incident0
",
        null,
        [EnableFolding = true]
    ),

    // 2) Spalten entfernen
    #"Entfernte Spalten" = Table.RemoveColumns(dbo_contract,{"customerid", "createdby"}),

    // 3) Spalte "createdon" duplizieren
    #"Duplizierte Spalte" = Table.DuplicateColumn(#"Entfernte Spalten", "createdon", "createdon - DateTime"),

    // 4) Datentypen anpassen (hier: "createdon" zu Date)
    #"Geänderter Typ" = Table.TransformColumnTypes(#"Duplizierte Spalte", {{"createdon", type date}}),

    // 5) Weitere Spalten entfernen
    #"Entfernte Spalten1" = Table.RemoveColumns(#"Geänderter Typ",{"firstresponsebykpiid",  "ownerid"}),

    // 6) Weitere Datentypen (hier: "caseage" zu Int64)
    #"Geänderter Typ1" = Table.TransformColumnTypes(#"Entfernte Spalten1", {{"caseage", Int64.Type}}),

    // 7) Fehler in "caseage" durch 1 ersetzen
    #"Ersetzte Fehler" = Table.ReplaceErrorValues(#"Geänderter Typ1", {{"caseage", 1}}),

    // 8) Weitere Spalten entfernen
    #"Entfernte Spalten2" = Table.RemoveColumns(#"Ersetzte Fehler",{"owningteam", "pdw_agreement_id", "pdw_impact_code", "primarycontactid"}),

    // ---------------------------------------------
    // 9) Beispiel: JSON-Parsing einbauen
    //    Wir legen eine neue Spalte an, die das JSON parst und in ein Record schreibt
    #"Hinzufügen JSON" = Table.AddColumn(#"Entfernte Spalten2", "ParsedJSON",
        each
            let
                // Hier steht dein JSON-String, den du parsen möchtest
                MyJSON = "{""FailureTime"":""2024-10-21T15:06:21Z"",""Name"":""Anfrage - Erste Antwort"",""Status"":0,""WarningTime"":""2024-10-21T07:36:21Z"",""CreatedOn"":""2024-10-21T07:06:23Z""}",
                // In ein Record umwandeln
                ParsedRecord = Json.Document(MyJSON),
                // Felder auslesen
                FailureTime = ParsedRecord[FailureTime],
                Name = ParsedRecord[Name],
                Status = ParsedRecord[Status],
                WarningTime = ParsedRecord[WarningTime],
                CreatedOn = ParsedRecord[CreatedOn]
            in
                // Rückgabe als Record, damit wir diese Felder im nächsten Schritt expandieren können
                [
                    FailureTime = FailureTime,
                    Name = Name,
                    Status = Status,
                    WarningTime = WarningTime,
                    CreatedOn = CreatedOn
                ]
    ),

    // 10) Die Record-Spalte "ParsedJSON" aufklappen, damit jede JSON-Property zu einer eigenen Spalte wird
    #"Erweiterte JSON" = Table.ExpandRecordColumn(
        #"Hinzufügen JSON", 
        "ParsedJSON", 
        {"FailureTime", "Name", "Status", "WarningTime", "CreatedOn"},
        {"FailureTime", "Name", "Status", "WarningTime", "CreatedOn"}
    ),
    #"Entfernte Spalten3" = Table.RemoveColumns(#"Erweiterte JSON",{"pdw_queue_id", "pdw_problem_id", "pdw_tier_id", "pdw_subtype_id", "pdw_vendor_id", "slainvokedid", "pdw_resolutiontype_id", "customersatisfactioncode", "modifiedby", "owningbusinessunit", "pdw_incidenttemplate_id", "pdw_initialrequest_id", "pdw_urgency_code"}),
    #"Ersetzter Wert" = Table.ReplaceValue(#"Entfernte Spalten3",null,"Niedrig",Replacer.ReplaceValue,{"pdw_priority_codename"}),
    #"Hinzugefügte benutzerdefinierte Spalte" = Table.AddColumn(#"Ersetzter Wert", "pdw_priority_codename_gbl", each if [createdbyname] = "# KelverionDynamicsIntegration" 
        and [createdon] < #date(2025, 1, 1) 
     then "Niedrig" 
     else [pdw_priority_codename]),
    #"Hinzugefügte benutzerdefinierte Spalte1" = Table.AddColumn(#"Hinzugefügte benutzerdefinierte Spalte", "ScomBased", each if [createdbyname] = "# KelverionDynamicsIntegration" 
             then -1
     else 0),
    #"Geänderter Typ2" = Table.TransformColumnTypes(#"Hinzugefügte benutzerdefinierte Spalte1",{{"ScomBased", type logical}}),
    #"Hinzugefügte benutzerdefinierte Spalte2" = Table.AddColumn(#"Geänderter Typ2", "IncidentIDLink", each "https://psop.crm4.dynamics.com/main.aspx?appid=06279b79-51c2-ec11-9840-000d3ab486b4&pagetype=entityrecord&etn=incident&id=" & Text.From([incidentid]))
in
    #"Hinzugefügte benutzerdefinierte Spalte2"
